var i=3;var n=`003-mise-en-place-and-kitchen-organization`;var a=`001`;var r={en:`Mise en Place and Kitchen Organization`,ua:`Мізанплас та організація робочого місця`};var o={short:`Mise en place means putting ingredients, tools, and tasks in order before active cooking. It reduces missed steps and makes fast operations easier to control while preserving food-safe storage conditions.`,sections:[{title:`Core idea`,text:`The French term literally means “put in place.” In practice it is an organizational system: interpret the recipe, identify dependencies, gather tools, prepare ingredients, and arrange them in the order of use.`},{title:`Scientific / practical principles`,text:`A reliable station minimizes unnecessary motion and decision-making under heat or time pressure. However, mise en place does not mean leaving perishable foods at room temperature for an extended period; cold ingredients remain refrigerated until needed.`},{title:`How to apply it`,text:`Read the full recipe, check inventory, wash produce, measure dry ingredients and prepare safe cutting areas. Keep raw proteins separate from ready-to-eat components, set out clean utensils and preheat equipment at the appropriate moment.`},{title:`Practical example`,text:`Before stir-frying, slice vegetables uniformly, mix the sauce and place a heatproof plate nearby. Once the wok is hot, ingredients can be added in sequence without pausing to peel garlic.`},{title:`Common mistakes and limitations`,text:`Preparing every ingredient hours in advance can compromise freshness or safety. Also avoid cluttering the workspace, forgetting a required tool, or placing raw poultry near chopped salad ingredients.`}]};var s={short:`Мізанплас означає підготувати інгредієнти, інструменти та порядок дій перед активним приготуванням. Це зменшує кількість пропущених кроків і допомагає працювати швидко, не порушуючи правил зберігання продуктів.`,sections:[{title:`Суть`,text:`Французький вислів буквально означає «розкласти все на свої місця». На практиці це система організації: прочитати рецепт, визначити залежності між діями, зібрати інвентар, підготувати продукти й розмістити їх у порядку використання.`},{title:`Наукові та практичні принципи`,text:`Продумане робоче місце зменшує зайві рухи та кількість термінових рішень біля гарячої плити. Водночас мізанплас не означає залишати швидкопсувні продукти надовго за кімнатної температури: їх тримають охолодженими до моменту використання.`},{title:`Як застосовувати`,text:`Прочитайте весь рецепт, перевірте запаси, помийте овочі, зважте сухі компоненти та підготуйте безпечні зони нарізання. Сире м’ясо відокремте від готових до споживання продуктів, підготуйте чистий інвентар і вчасно розігрійте обладнання.`},{title:`Практичний приклад`,text:`Перед швидким смаженням у воці однаково наріжте овочі, змішайте соус і поставте поруч термостійку тарілку. Після нагрівання вока ви зможете додавати продукти послідовно, не відволікаючись на часник.`},{title:`Поширені помилки й обмеження`,text:`Надто рання підготовка всіх продуктів може погіршити свіжість або безпечність. Також не захаращуйте робочу поверхню й не кладіть сиру птицю поруч із нарізаними інгредієнтами для салату.`}]};var c=[4,8,9,277];var l=`References / Джерела`;var p=[`https://www.cacfp.org/2024/05/07/culinary-basics-mise-en-place/`,`https://www.who.int/activities/promoting-safe-food-handling/five-key-to-safer-food/`];var d={id:3,slug:n,group:`001`,title:r,en:o,ua:s,related:c,referenceTitle:l,references:p};export{d as default,o as en,a as group,i as id,l as referenceTitle,p as references,c as related,n as slug,r as title,s as ua};